/*
 * Node.js entry point for the ES5 test suite generated by
 * scripts/build-es5-tests.js (copied to test-es5/run.js). It needs no
 * npm install and runs on every Node.js version from 0.10 onwards:
 *
 *   node test-es5/run.js [title-substring]
 *
 * The compiled tests load the built CommonJS (index.js, lib/) and browser
 * (validator.js, validator.min.js) outputs, never src/.
 */

'use strict';

var path = require('path');
var createTestRunner = require('./runner');
var manifest = require('./manifest.json'); // eslint-disable-line import/no-unresolved

/*
 * Test-only shims for ES2015+ APIs that the test files (not the library) use.
 * They are installed only when missing. This cannot hide a library dependency
 * on them, because the ESLint config forbids these APIs in src/.
 */
var shims = [];
/* eslint-disable no-extend-native */
if (typeof String.prototype.repeat !== 'function') {
  String.prototype.repeat = function (count) {
    return new Array(count + 1).join(String(this));
  };
  shims.push('String.prototype.repeat');
}
/* eslint-enable no-extend-native */
if (typeof Buffer.from !== 'function') {
  Buffer.from = function (string) {
    return new Buffer(string); // eslint-disable-line no-buffer-constructor
  };
  shims.push('Buffer.from');
}

var runner = createTestRunner();
global.describe = runner.describe;
global.it = runner.it;

console.log('ES5 test suite on Node.js ' + process.version +
  (shims.length ? ' (test-only shims: ' + shims.join(', ') + ')' : ''));

manifest.files.forEach(function (file) {
  runner.load(file, function () {
    // eslint-disable-next-line global-require, import/no-dynamic-require
    require(path.join(__dirname, file));
  });
});

/*
 * Tests that cannot work on a given Node.js version for reasons outside the
 * library. They are reported as pending, with the reason.
 */
var skip = {};
if (/^v0\.10\./.test(process.version)) {
  skip['Validators > should bind validator to the window if no module loaders are available'] =
    'Node.js 0.10 vm.createContext() copies the sandbox, so writes to the global never reach `window`';
}

var result = runner.run({
  grep: process.argv[2] || null, // only run tests whose full title contains this text
  skip: skip,
});
if (result.failed || result.passed === 0) {
  // Exit non-zero once the output is flushed (process.exitCode needs Node.js >= 0.11.8).
  process.on('exit', function () {
    process.exit(1);
  });
}
